def transform(grid):
    # Each 3x3 patch is represented by its non-background marker, if present.
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            colors = {grid[i][j] for i in range(r, min(r + 3, h))
                      for j in range(c, min(c + 3, w)) if grid[i][j] not in (0, 5)}
            row.append(min(colors) if colors else 0)
        out.append(row)
    return out
